const path = await import('node:path');
const root = path.join(nodeRepl.homeDir, '.codex/plugins/cache/openai-bundled/chrome/26.715.72359');
async function walk(dir, depth=2) {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  let res = [];
  for (const e of entries) {
    res.push({path: path.relative(root, path.join(dir,e.name)), dir: e.isDirectory()});
    if (e.isDirectory() && depth>0) {
      try { res.push(...await walk(path.join(dir,e.name), depth-1)); } catch {}
    }
  }
  return res;
}
nodeRepl.write(JSON.stringify(await walk(root,2), null, 2));

